function maxRemovals($s) {
    $n = strlen($s);
    $dp = array_fill(0, $n + 1, 0);
    for ($i = 1; $i <= $n; $i++) {
        $dp[$i] = $dp[$i - 1];
        for ($j = 0; $j < $i; $j++) {
            if (canRemove($s, $j, $i - 1)) {
                $dp[$i] = max($dp[$i], $dp[$j] + 1);
            }
        }
    }
    return $dp[$n];
}

function canRemove($s, $left, $right) {
    if ($left >= $right) return false;
    for ($i = $left; $i < $right; $i++) {
        $prev = $s[$i];
        $next = $s[$i + 1];
        if (ord($next) - ord($prev) == 1) {
            return true;
        }
    }
    return false;
}

